package com.nse.dashboard.service;import com.nse.dashboard.agent.*;import com.nse.dashboard.model.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.util.*;@Service public class DashboardService { @Autowired private OIAnalysisAgent oiAgent; @Autowired private SentimentAgent sentimentAgent; @Autowired private SmartMoneyAgent smartMoneyAgent; @Autowired private TrapAgent trapAgent; public DashboardResponse generate(List<OptionData> optionData,List<ParticipantData> participantData){ Map<String,Double> levels=oiAgent.analyze(optionData); DashboardResponse res=new DashboardResponse(); res.setSupport(levels.get("support")); res.setResistance(levels.get("resistance")); res.setMarketBias(sentimentAgent.analyze(optionData)); res.setSmartMoney(smartMoneyAgent.analyze(participantData)); res.setTrapSignal(trapAgent.detect(optionData)); return res;}}